import type { Metadata } from "next";
import { GhostVpsLanding } from "@/components/marketing/apphostingtemplate/GhostVpsLanding";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { APP_URL, ProductOffersJsonLd, FaqJsonLd } from "@/components/marketing/StructuredData";
import { PLANS, FAQS } from "@/components/marketing/apphostingtemplate/data";

// PREVIEW ROUTE — not a live product page. Kept out of search + sitemaps.
export const metadata: Metadata = {
  title: "Host Ghost on a VPS you own · Nxeon",
  description:
    "Self-host Ghost on a Nxeon VPS in ~47 seconds. One-command ghost-cli install with Ubuntu, Node, MySQL, Nginx and free SSL preconfigured — unlimited members, full root, from $6/mo.",
  robots: { index: false, follow: false },
};

export default function Page() {
  return (
    <>
      {/* Product + Offer and FAQ structured data (reuses the shared StructuredData
          helpers; mirrors the visible plans and FAQ). */}
      <ProductOffersJsonLd
        name="Ghost VPS hosting on Nxeon"
        description="The VPS Ghost needs, preconfigured — Ubuntu, Node.js, MySQL 8, Nginx and free SSL with a one-command ghost-cli install. Full root, unlimited members, no lock-in."
        url={`${APP_URL}/vps`}
        offers={PLANS.map((p) => ({ name: `${p.tier} — Ghost VPS`, price: p.priceUsd }))}
      />
      <FaqJsonLd items={FAQS} />
      <GhostVpsLanding reviewBadges={<ReviewBadges />} />
    </>
  );
}

